RULES = [
    {"id": "tn-r1", "node": "q-tn-modal", "text": "After a modal (will, would, can, could, may, might, shall, should, must) the verb is the bare base form: no -s, no -ed, no -ing, no to. Words placed between the modal and the verb (such as 'without any pressure') do not change this.",
     "ok": "Regional bodies will, without any pressure, comply.", "bad": "Regional bodies will, without any pressure, complies."},
    {"id": "tn-r2", "node": "q-tn-subjunctive", "text": "After demand, insist, suggest, recommend, request, propose, order + that, the verb is the base form (subjunctive) whatever the subject. 'Demand' cannot take 'me to': say 'demanded that I ...'.",
     "ok": "She demanded that I swallow the medication.", "bad": "She demanded me to swallow the medication."},
    {"id": "tn-r3", "node": "q-tn-stative", "text": "Verbs of perception, mental state, feeling, or possession (see, hear, know, think, believe, want, like, love, hate, own, have meaning possess, belong, resemble, seem, appear, remember, mean) describe a state rather than an ongoing action, so they do not take -ing even in a sentence that feels like 'right now'. 'Have' keeps this rule only when it means possess; when it names an action (have breakfast, have a bath, have a look) it can take -ing.",
     "ok": "He owns three shops in that market.", "bad": "He is owning three shops in that market."},
    {"id": "tn-r4", "node": "q-tn-sincefor", "text": "'Since' names the point at which an unbroken period began (since 2008, since Monday, since morning); 'for' names the period's length (for two years, for a week) and never follows 'since'. A clause that opens with 'since' is in the simple past; the clause it supports is in the present perfect (or past perfect, if the whole sentence is already set in the past).",
     "ok": "I have not met him since he left the city.", "bad": "I have not met him since twenty years."},
    {"id": "tn-r5", "node": "q-tn-definite", "text": "The present perfect reports an action with no stated point in past time, or one still connected to the present. The instant a sentence names a finished point in the past — yesterday, last year, in 1998, two days ago, 'when' + simple past — the verb must switch to simple past.",
     "ok": "She submitted the report yesterday.", "bad": "She has submitted the report yesterday."},
    {"id": "tn-r6", "node": "q-tn-sequence", "text": "When a sentence reports two past actions, the one that happened first takes the past perfect and the one that happened second takes the simple past, usually signalled by 'before', 'after', 'by the time', or '...found that...'. When the same 'by the time' signpost points at the future instead, the later action takes the future perfect, not the simple future.",
     "ok": "By the time the manager arrived, the workers had already left.", "bad": "By the time the manager arrived, the workers already left."},
    {"id": "tn-r7", "node": "q-tn-itstime", "text": "'It is (high) time' is followed by a subject and the simple past — not a modal such as 'should' — to say something is overdue, or by 'to' and the base verb with the subject left out.",
     "ok": "It is time you left for the station.", "bad": "It is time you should leave for the station."},
    {"id": "tn-r8", "node": "q-tn-canable", "text": "'Can' and 'could' already mean 'is/was able to', so adding 'be able to' after them in the same clause doubles up the same idea and is treated as an error. 'Could' on its own covers past ability (I could swim as a child), a polite request (Could you help me?), and a remote or theoretical possibility (There could be a storm tonight).",
     "ok": "I will not be able to come tomorrow. I cannot come tomorrow.", "bad": "I cannot be able to come tomorrow."},
    {"id": "tn-r9", "node": "q-tn-maymight", "text": "'May' expresses a real but moderate possibility, permission, or (in a fixed pattern) a wish, as in 'May you live long!'. 'Might' expresses a weaker, more remote possibility than 'may'. 'Must', used for a conclusion rather than an order, expresses near certainty drawn from evidence that is already known.",
     "ok": "He might pass, though I have little hope. He stays in five-star hotels; he must be rich.", "bad": "He must pass, though I have little hope (must is too strong for a guess the speaker doubts)."},
    {"id": "tn-r10", "node": "q-tn-shallwill", "text": "When the speaker is making a command, promise, threat or compulsion that falls on the listener or on a third person, the verb is 'shall', not 'will', as in 'You shall leave at once' or 'Trespassers shall be prosecuted'. For the speaker's own first-person promise, threat, determination or compulsion, the verb is 'will', as in 'I will help you' or 'I will punish you'. A plain statement of the future, with no such special force, keeps 'will' for every person in current usage.",
     "ok": "You shall be awarded for this. I will help you come what may.", "bad": "You will be awarded for this (drops the sense of a promise the speaker is making)."},
]

